contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  // Drive sudicideAnyone once from an arbitrary caller and observe whether the target contract's balance is zero afterwards.
  // The rule: if the caller is equal to c.smartfix_owner(), then after calling sudicideAnyone the contract's balance must be zero;
  // otherwise, the call must revert (so balance stays unchanged). We express this as a single assert relating the observed revert boolean
  // and the owner equality. This holds for the original P but is violated by the mutant that requires owner == address(0).
  function run(address caller, uint256 sendAmount) public payable {
    // prepare precondition: this test contract must hold enough ETH to forward
    require(address(this).balance >= sendAmount);

    // record balance before
    uint256 before = address(c).balance;

    // check owner equality via public getter
    address owner = c.smartfix_owner();
    bool ownerMatches = (owner == caller);

    // perform the call from the specified caller by using low-level call with provided value.
    // The call may succeed (and selfdestruct c) or revert. Capture success.
    (bool success,) = address(c).call{value: sendAmount}(abi.encodeWithSignature("sudicideAnyone()"));

    uint256 after = address(c).balance;

    // The general rule: (ownerMatches implies contract balance becomes zero) AND (not ownerMatches implies the call failed and balance unchanged).
    // Expressed compactly as a single assert comparing booleans and balances.
    assert( (ownerMatches && after == 0) || (!ownerMatches && !success && after == before) );
  }

  // Allow contract to receive ETH so tests can fund it
  receive() external payable {}
}

