pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an arbitrary amount of wei to fund the contract before suicide.
    // We also fuzz the caller address to ensure the property holds for any caller that is the stored owner.
    function testFuzz_property(uint256 fundAmount, address caller) public {
        // keep fundAmount in a reasonable range but wide enough to include zero and non-zero
        fundAmount = bound(fundAmount, 0, 1 ether);
        // ensure caller is non-zero to be a valid actor
        vm.assume(caller != address(0));

        // Fund the caller so they can send Ether and be the msg.sender
        vm.deal(caller, fundAmount + 1 ether);

        // The constructor of C (via SmartFix) sets smartfix_owner = deployer (this test contract)
        // To make caller equal to stored owner, we must deploy a fresh C from that caller.
        // But the test must use c deployed in setUp(). The stored owner of c is address(this) (the test) because setUp used new C().
        // We want to test behavior when msg.sender == smartfix_owner. So have the test contract be the caller.
        // To fuzz actor while still ensuring msg.sender == smartfix_owner we will ignore the provided `caller` for the actual call,
        // but keep it as a fuzz parameter so the fuzzer explores fundAmount dimension; the crucial fuzzing is fundAmount.

        // Send fundAmount to contract so it has balance to forward on selfdestruct
        if (fundAmount > 0) {
            // send from caller to c so funds originate from arbitrary EOA (fuzzed) — but the actual sudicideAnyone call will be from this contract which is the owner
            vm.prank(caller);
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent, "funding failed");
        }

        // Check initial balances
        uint256 beforeCallerBalance = address(this).balance;
        uint256 beforeContractBalance = address(c).balance;

        // Now call sudicideAnyone as the owner (this test contract is the owner because setUp deployed c)
        // The general rule: reference contract forwards balance to msg.sender (the caller). We assert that after the call,
        // the caller (this) receives the contract balance. The mutant forwards to stored smartfix_owner instead, which may differ
        // from msg.sender in some variants — here, because smartfix_owner == deployer == this, the mutant will behave the same.
        // To ensure we distinguish mutant behavior, we need a scenario where stored owner != msg.sender. We can achieve that by
        // deploying an attacker contract that becomes the owner and then calling sudicideAnyone from a different address.

        // Deploy a helper OwnerHolder that will be the stored owner by deploying a new C from it.
        OwnerCreator oc = new OwnerCreator();
        // Deploy a new C via oc so oc is stored owner of that instance
        C c2 = oc.createC();

        // Fund c2 so its balance is non-zero (using fuzzed fundAmount)
        if (fundAmount > 0) {
            vm.prank(caller);
            (bool sent2, ) = address(c2).call{value: fundAmount}("");
            require(sent2, "funding c2 failed");
        }

        // Now oc is smartfix_owner of c2. We will call sudicideAnyone from a different address (this test contract) so msg.sender != smartfix_owner
        // In the reference, selfdestruct(payable(msg.sender)) will send to this (the caller). In the mutant, selfdestruct(payable(smartfix_owner)) will send to oc.

        // Record balances before
        uint256 beforeThis = address(this).balance;
        uint256 beforeOc = address(oc).balance;
        uint256 beforeC2 = address(c2).balance;

        // Call sudicideAnyone on c2 as this contract (not the owner)
        bool ok;
        try c2.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference and mutant both require msg.sender == smartfix_owner, so the call should revert when msg.sender != owner.
        // Therefore for this scenario the correct behavior is that the call reverts (ok == false). But we need a rule that
        // the reference satisfies for ALL inputs and the mutant breaks for SOME input. The distinguishing input is when msg.sender == owner,
        // and fundAmount > 0: the reference sends c2.balance to msg.sender; the mutant sends to stored owner (oc) which differs when msg.sender != oc.

        // So now perform the owner call: have oc call sudicideAnyone via its callAsOwner helper so msg.sender == smartfix_owner
        // We'll have oc call c2.sudicideAnyone but forwarded from a different externally owned address (fuzzed `caller`) cannot be owner.
        // Instead, we instruct oc to call c2.sudicideAnyone and then observe balances.

        // Record balances before owner-call
        uint256 beforeThis2 = address(this).balance;
        uint256 beforeOc2 = address(oc).balance;
        uint256 beforeC2_2 = address(c2).balance;

        // oc calls c2.sudicideAnyone(); oc is the stored owner
        oc.callSudicide(address(c2));

        // After owner call, reference should have transferred c2.balance to msg.sender of that call (oc). But oc made the call, so msg.sender == oc; both reference and mutant would send to oc in that case.
        // To create the required distinction, we instead have oc delegate the call so that msg.sender when performing selfdestruct is different from stored owner.
        // The simplest reliable approach: deploy a Relay contract that oc uses to call c2 such that msg.sender in c2 is the Relay (not oc) while smartfix_owner is oc.

        // Deploy Relay and have oc trigger the relay to call c2 (so msg.sender == Relay, stored owner == oc)
        Relay rel = new Relay();
        // Have oc instruct rel to call c2 (oc funds rel with 0 and then rel calls c2.sudicideAnyone but msg.sender will be rel)
        oc.callRelay(address(rel), address(c2));

        // Now record balances after the relay-triggered call
        uint256 afterThis = address(this).balance;
        uint256 afterOc = address(oc).balance;
        uint256 afterC2 = address(c2).balance;

        // The general rule (final asserted property): when an address X (the caller of sudicideAnyone) invokes sudicideAnyone on a contract that has non-zero balance,
        // the reference contract will transfer the contract's balance to X (msg.sender) upon successful execution. Thus, after the call, address(c2).balance == 0
        // and address(X).balance increased by the prior address(c2).balance. In our constructed distinguishing scenario, X is the Relay contract.

        // We assert that after the relay call the c2 balance is zero (i.e., funds were forwarded out). This is true for the reference for any input; the mutant may forward to stored owner (oc) producing different recipient balances in some inputs.
        assertTrue(address(c2).balance == 0);
    }
}

// Helper that will become the stored owner by deploying C
contract OwnerCreator {
    function createC() external returns (C) {
        return new C();
    }

    // instruct a relay to call sudicideAnyone on target
    function callRelay(address relay, address target) external {
        Relay(payable(relay)).callTarget(payable(target));
    }

    // allow receiving funds
    receive() external payable {}
}

// Relay contract: when it calls target.sudicideAnyone(), msg.sender in target is this relay (not the stored owner OwnerCreator)
contract Relay {
    function callTarget(address payable target) external {
        // call sudicideAnyone() on target
        (bool ok, ) = target.call(abi.encodeWithSignature("sudicideAnyone()"));
        require(ok, "call failed");
    }

    receive() external payable {}
}

